import React, { useEffect, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUpRight, Bell, Bookmark, Boxes, Check, ChevronDown, CircleHelp, Code2, Compass, ExternalLink, FolderKanban, Gamepad2, Github, Heart, Home, Leaf, LockKeyhole, LogOut, Menu, MessageCircle, Moon, MoreHorizontal, Plus, Search, Settings2, ShieldCheck, Sparkles, Sprout, Sun, Users, Wallet, WandSparkles, X } from 'lucide-react';
